function validate([s]) {
  if (s.length < 1 || s.length > 100) return 's needs 1 to 100 characters.';
  if (!/^[01]+$/.test(s)) return 's may only contain 0 and 1.';
  if (s[0] !== '1') return 's must start with 1.';
  return null;
}

