function generate(rand, size) {
  const n = size === 'large' ? 80 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 10);
  if (rand() < 0.5) {
    const ones = 1 + Math.floor(rand() * n);
    return ['1'.repeat(ones) + '0'.repeat(n - ones)];
  }
  let s = '1';
  const density = rand();
  while (s.length < n) s += rand() < density ? '1' : '0';
  return [s];
}
